// SwiftUI
struct DeleteButton: View {
    @State private var isOpen = false
    var body: some View {
        Button("삭제") { isOpen = true }
            .background {
                JdAlertDialog(isPresented: $isOpen,
                              title: "삭제할까요?", message: "되돌릴 수 없습니다.",
                              confirmLabel: "삭제", cancelLabel: "취소",
                              isDestructive: true,
                              onConfirm: { delete() },
                              onCancel: { })
            }
    }
}
